# Show top-k at positions preceding the ' Wait' tokens in loop texts, and compare with finished positions
def show(ti, pos, n=10):
    print('text',ti,'pos',pos,'ctx', repr(''.join(tok.decode([i]) for i in ids_all[ti][max(0,pos-8):pos+1])))
    for k in range(n):
        tid=int(top_ids[ti,pos,k]); lp=float(top_lp[ti,pos,k])
        print('   ', repr(tok.decode([tid])), round(lp,3))
for ti in [0,1,2]:
    ids=ids_all[ti]
    toks=[tok.decode([i]) for i in ids]
    wpos=[i for i,t in enumerate(toks) if t==' Wait']
    for p in wpos[-2:]:
        show(ti,p-1)
    print('====')
